# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: `ds test` commands -- the repo's test tiers (.agents/agents.md, "Testing"). Unit
#          tests need nothing running; smoke and e2e drive the running delulu-smash app in a
#          real browser (tests/services/ui/e2e), so they check it is up first.
#
# Example CLI Commands:
#   1. Unit tests (fast, what a plain pytest runs):   ds test
#   2. The short browser run (about a minute):        ds test smoke
#   3. Every browser test (a few minutes):            ds test e2e
#   4. Only tests matching a name:                    ds test e2e -k e2e_terminal
# ---------------------------------------------------------------------------
from __future__ import annotations

import subprocess
import sys
from typing import Annotated

import typer
from ds.cli.ui import APP_NAME, ready
from ds.cli.util import run_cmd
from ds.util.const import REPO_DIR

__all__ = ["test_app"]

test_app = typer.Typer(help="Run the tests: unit (default), smoke, e2e", invoke_without_command=True)

E2E_DIR = "tests/services/ui/e2e"
Match = Annotated[str | None, typer.Option("-k", help="Only tests whose name matches (pytest's -k)")]


def _pytest(*args: str, match: str | None = None) -> None:
    cmds = [sys.executable, "-m", "pytest", *args, *(["-k", match] if match else [])]
    try:
        run_cmd(cmds, cwd=REPO_DIR)
    except subprocess.CalledProcessError as exc:
        # failing tests are a result, not a crash: pass pytest's exit code on
        raise typer.Exit(exc.returncode) from None


def _browser_tests(marker: str, match: str | None) -> None:
    if not ready():
        typer.echo(f"{APP_NAME} isn't answering: start it with `ds ui restart`, then run this again.", err=True)
        raise typer.Exit(1)
    _pytest("-m", marker, E2E_DIR, match=match)


@test_app.callback()
def unit(ctx: typer.Context, match: Match = None) -> None:
    """Unit tests: no browser, no app, no network (what a plain `pytest` runs)"""
    if ctx.invoked_subcommand is None:
        _pytest(match=match)


@test_app.command("smoke")
def smoke(match: Match = None) -> None:
    """The short browser run: what must never break (needs the app running)"""
    _browser_tests("smoke", match)


@test_app.command("e2e")
def e2e(match: Match = None) -> None:
    """Every browser test (needs the app running)"""
    _browser_tests("e2e", match)
